import * as React from "react";
import { CircleCheck, Clock, CalendarDays, type LucideIcon } from "lucide-react";
import { t } from "@/lib/i18n";

export type AvailabilityStatus = "available" | "busy" | "scheduled";

const MAP: Record<
  AvailabilityStatus,
  { icon: LucideIcon; labelKey: "availability.available" | "availability.busy" | "availability.scheduled"; className: string }
> = {
  available: {
    icon: CircleCheck,
    labelKey: "availability.available",
    className: "bg-success-tint text-success",
  },
  busy: {
    icon: Clock,
    labelKey: "availability.busy",
    className: "bg-surface-sunk text-ink-soft",
  },
  scheduled: {
    icon: CalendarDays,
    labelKey: "availability.scheduled",
    className: "bg-accent-tint text-accent-dark",
  },
};

/**
 * Availability pill — status conveyed by icon + text label together, never by
 * color alone (SPEC §10 / design system).
 */
export function Availability({ status }: { status: AvailabilityStatus }) {
  const { icon: Icon, labelKey, className } = MAP[status];
  return (
    <span
      className={[
        "inline-flex items-center gap-1.5 whitespace-nowrap rounded-pill px-2.5 py-1 text-sm font-bold",
        className,
      ].join(" ")}
    >
      <Icon size={15} strokeWidth={2.25} aria-hidden="true" />
      {t(labelKey)}
    </span>
  );
}
