import { Suspense } from "react";
import { Card } from "@/components/ui/Card";
import { BrowseFilters } from "@/components/customer/BrowseFilters";
import { ListenerCard } from "@/components/customer/ListenerCard";
import { listApprovedProviders, listFavoriteIds } from "@/lib/db/queries";
import { getVoiceIntroSignedUrl } from "@/lib/storage";
import { getProfile } from "@/lib/auth";
import { t } from "@/lib/i18n";

export const metadata = { title: `${t("browse.title")} · ${t("app.name")}` };

export default async function BrowsePage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | undefined>>;
}) {
  const sp = await searchParams;
  const maxPrice = sp.maxPrice ? Number(sp.maxPrice) : undefined;

  const profile = await getProfile();
  const isCustomer = profile?.role === "customer";

  const [providers, favoriteIds] = await Promise.all([
    listApprovedProviders({
      topic: sp.topic || undefined,
      language: sp.language || undefined,
      availableNow: sp.available === "1" || undefined,
      maxPriceCents:
        typeof maxPrice === "number" && Number.isFinite(maxPrice)
          ? maxPrice
          : undefined,
    }),
    isCustomer ? listFavoriteIds(profile.id) : Promise.resolve([]),
  ]);
  const favoriteSet = new Set(favoriteIds);

  const withAudio = await Promise.all(
    providers.map(async (provider) => ({
      provider,
      audioUrl: await getVoiceIntroSignedUrl(provider.voice_intro_path),
    })),
  );

  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-col gap-1.5">
        <h1 className="text-h1">{t("browse.title")}</h1>
        <p className="text-lg text-ink-soft">{t("browse.subtitle")}</p>
      </div>

      <Suspense fallback={null}>
        <BrowseFilters />
      </Suspense>

      <p className="text-base font-bold text-ink-soft" aria-live="polite">
        {t("browse.resultsCount", { count: providers.length })}
      </p>

      {withAudio.length === 0 ? (
        <Card>
          <p className="text-base text-ink-soft">{t("browse.noResults")}</p>
        </Card>
      ) : (
        <ul className="grid grid-cols-2 gap-5 max-md:grid-cols-1">
          {withAudio.map(({ provider, audioUrl }) => (
            <ListenerCard
              key={provider.id}
              provider={provider}
              audioUrl={audioUrl}
              canFavorite={isCustomer}
              isFavorite={favoriteSet.has(provider.id)}
            />
          ))}
        </ul>
      )}
    </div>
  );
}
