"use client";

import * as React from "react";
import { CircleAlert, CreditCard, ShieldCheck, Check } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Field, Input } from "@/components/ui/Field";
import { createBooking } from "@/app/(customer)/actions";
import { formatCents } from "@/lib/format";
import { t } from "@/lib/i18n";
import { donationPresetsCents, type BlockMinutes } from "@/lib/pricing";

export interface BookingProvider {
  id: string;
  displayName: string;
  prices: Record<BlockMinutes, number>;
  overagePerMinCents: number;
}

const BLOCKS: BlockMinutes[] = [15, 30, 45];

const TILE =
  "flex cursor-pointer flex-col gap-1 rounded-card border bg-surface p-4 text-left has-[:focus-visible]:shadow-[0_0_0_3px_var(--color-focus)]";
const TILE_ON = "border-2 border-primary bg-primary-tint";
const TILE_OFF = "border-border-strong hover:bg-primary-tint/40";

export function BookingForm({
  provider,
  defaultMode,
}: {
  provider: BookingProvider;
  defaultMode: "now" | "scheduled";
}) {
  const [block, setBlock] = React.useState<BlockMinutes>(30);
  const [mode, setMode] = React.useState<"now" | "scheduled">(defaultMode);
  const [scheduledAt, setScheduledAt] = React.useState("");
  // The donation: a preset (cents) or "custom" with a free-typed dollar amount.
  const [selection, setSelection] = React.useState<number | "custom">(
    provider.prices[30],
  );
  const [customDollars, setCustomDollars] = React.useState("");
  const [submitting, setSubmitting] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = React.useState<Record<string, string>>({});

  const floorCents = provider.prices[block];
  const presets = donationPresetsCents(floorCents);

  function changeBlock(minutes: BlockMinutes) {
    setBlock(minutes);
    // Re-anchor the donation to the new block's suggested amount.
    setSelection(provider.prices[minutes]);
    setCustomDollars("");
  }

  const customCents = Math.round((parseFloat(customDollars) || 0) * 100);
  const customValid = customCents >= floorCents;
  const donationValid = selection !== "custom" || customValid;
  const donationCents =
    selection === "custom"
      ? customValid
        ? customCents
        : floorCents
      : selection;

  async function onConfirm() {
    setSubmitting(true);
    setError(null);
    setFieldErrors({});
    const res = await createBooking({
      providerId: provider.id,
      blockMinutes: block,
      startMode: mode,
      scheduledAt:
        mode === "scheduled" && scheduledAt
          ? new Date(scheduledAt).toISOString()
          : undefined,
      donationCents,
    });
    // Success redirects; only errors return.
    if (res?.error) {
      setError(res.error);
      setFieldErrors(res.fieldErrors ?? {});
      setSubmitting(false);
    }
  }

  return (
    <div className="flex flex-col gap-6">
      {error ? (
        <p
          role="alert"
          className="flex items-start gap-2 rounded-card border-l-4 border-alert bg-alert-tint px-4 py-3 text-base"
        >
          <CircleAlert size={20} aria-hidden="true" className="mt-0.5 text-alert" />
          {error}
        </p>
      ) : null}

      <fieldset className="flex flex-col gap-3">
        <legend className="text-h3">{t("booking.chooseLength")}</legend>
        <div className="grid grid-cols-3 gap-3 max-sm:grid-cols-1">
          {BLOCKS.map((minutes) => {
            const selected = block === minutes;
            return (
              <label
                key={minutes}
                className={[TILE, selected ? TILE_ON : TILE_OFF].join(" ")}
              >
                <input
                  type="radio"
                  name="block"
                  value={minutes}
                  checked={selected}
                  onChange={() => changeBlock(minutes)}
                  className="sr-only"
                />
                <span className="flex items-center justify-between">
                  <span className="text-lg font-bold text-ink">
                    {t("booking.minutes", { minutes })}
                  </span>
                  {selected ? (
                    <Check size={18} strokeWidth={2.5} aria-hidden="true" className="text-primary" />
                  ) : null}
                </span>
                <span className="text-base font-bold text-ink-soft">
                  {formatCents(provider.prices[minutes])}
                </span>
              </label>
            );
          })}
        </div>
      </fieldset>

      <fieldset className="flex flex-col gap-3">
        <legend className="text-h3">{t("booking.donationHeading")}</legend>
        <div className="grid grid-cols-4 gap-3 max-sm:grid-cols-2">
          {presets.map((cents, i) => {
            const selected = selection === cents;
            return (
              <label
                key={cents}
                className={[TILE, selected ? TILE_ON : TILE_OFF].join(" ")}
              >
                <input
                  type="radio"
                  name="donation"
                  checked={selected}
                  onChange={() => {
                    setSelection(cents);
                    setCustomDollars("");
                  }}
                  className="sr-only"
                />
                <span className="text-lg font-bold text-ink">
                  {formatCents(cents)}
                </span>
                {i === 0 ? (
                  <span className="text-sm font-bold text-primary-dark">
                    {t("booking.donationSuggested")}
                  </span>
                ) : null}
              </label>
            );
          })}
          <label
            className={[
              TILE,
              "justify-center",
              selection === "custom" ? TILE_ON : TILE_OFF,
            ].join(" ")}
          >
            <input
              type="radio"
              name="donation"
              checked={selection === "custom"}
              onChange={() => setSelection("custom")}
              className="sr-only"
            />
            <span className="text-lg font-bold text-ink">
              {t("booking.donationCustom")}
            </span>
          </label>
        </div>
        {selection === "custom" ? (
          <Field
            label={t("booking.donationCustomLabel")}
            error={
              customDollars && !customValid
                ? t("booking.donationBelowMin", { min: formatCents(floorCents) })
                : undefined
            }
          >
            {(p) => (
              <Input
                {...p}
                type="number"
                min={floorCents / 100}
                step="1"
                inputMode="decimal"
                value={customDollars}
                onChange={(e) => setCustomDollars(e.target.value)}
              />
            )}
          </Field>
        ) : null}
        <p className="text-sm text-ink-soft">
          {t("booking.donationMinHint", { min: formatCents(floorCents) })}
        </p>
      </fieldset>

      <fieldset className="flex flex-col gap-3">
        <legend className="text-h3">{t("booking.startHeading")}</legend>
        <div className="flex flex-col gap-2">
          {(["now", "scheduled"] as const).map((value) => (
            <label
              key={value}
              className="flex items-center gap-3 rounded-card border border-border-strong bg-surface px-4 py-3 text-base font-bold text-ink has-[:focus-visible]:shadow-[0_0_0_3px_var(--color-focus)]"
            >
              <input
                type="radio"
                name="mode"
                value={value}
                checked={mode === value}
                onChange={() => setMode(value)}
                className="size-5"
              />
              {value === "now" ? t("booking.startNow") : t("booking.startScheduled")}
            </label>
          ))}
