/** Format integer cents as a US dollar string, e.g. 2400 → "$24". */
export function formatCents(cents: number): string {
  const dollars = cents / 100;
  const hasFraction = cents % 100 !== 0;
  return dollars.toLocaleString("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: hasFraction ? 2 : 0,
    maximumFractionDigits: 2,
  });
}

/** Price summary for a block, e.g. "$24 / 30 min". */
export function formatBlockPrice(cents: number, minutes: number): string {
  return `${formatCents(cents)} / ${minutes} min`;
}

/** Rating to one decimal, e.g. 4.9. */
export function formatRating(avg: number): string {
  return avg.toFixed(1);
}
