export type BlockMinutes = 15 | 30 | 45;

/** Minimal provider shape needed to price a block. */
export interface BlockPricing {
  price_block_15_cents: number;
  price_block_30_cents: number;
  price_block_45_cents: number;
}

const DEFAULT_COMMISSION_RATE = 0.05;

/** Platform commission rate from config, clamped to [0, 1]; 0.05 fallback. */
export function getCommissionRate(): number {
  const raw = Number(process.env.PLATFORM_COMMISSION_RATE ?? DEFAULT_COMMISSION_RATE);
  if (!Number.isFinite(raw) || raw < 0 || raw > 1) return DEFAULT_COMMISSION_RATE;
  return raw;
}

/** Round to the nearest cent, half-up. Inputs are non-negative money amounts. */
export function roundHalfUp(value: number): number {
  return Math.floor(value + 0.5);
}

/** The block price (cents) a customer authorises at booking time. */
export function priceForBlock(
  provider: BlockPricing,
  blockMinutes: BlockMinutes,
): number {
  switch (blockMinutes) {
    case 15:
      return provider.price_block_15_cents;
    case 30:
      return provider.price_block_30_cents;
    case 45:
      return provider.price_block_45_cents;
  }
}

/**
 * Resolve a customer-chosen donation to integer cents. The listener's block
 * price is the SUGGESTED amount and the FLOOR: a customer may give more, never
 * less, so the listener always receives at least their stated rate (dignity is
 * the product — see CLAUDE.md). Sub-floor or invalid input clamps up to the floor.
 */
export function resolveDonationCents(
  chosenCents: number,
  floorCents: number,
): number {
  const chosen = Math.floor(Number(chosenCents) || 0);
  return Math.max(floorCents, chosen);
}
