import en from "@/messages/en.json";

/**
 * Tiny, dependency-free i18n helper. English-only for now, but the app reads
 * every user-facing string through `t()` so the catalog can be swapped or
 * extended later (see CLAUDE.md rule 7). No hard-coded UI strings in components.
 */

type Messages = typeof en;

/** Dotted key paths into the message catalog, e.g. "auth.signInTitle". */
type DottedKeys<T, Prefix extends string = ""> = {
  [K in keyof T & string]: T[K] extends string
    ? `${Prefix}${K}`
    : DottedKeys<T[K], `${Prefix}${K}.`>;
}[keyof T & string];

export type MessageKey = DottedKeys<Messages>;

function lookup(key: string): string | undefined {
  return key
    .split(".")
    .reduce<unknown>(
      (acc, part) =>
        acc && typeof acc === "object"
          ? (acc as Record<string, unknown>)[part]
          : undefined,
      en,
    ) as string | undefined;
}

/**
 * Resolve a message by key, with optional `{name}`-style interpolation.
 * Returns the key itself if missing so a gap is visible rather than silent.
 */
export function t(
  key: MessageKey,
  vars?: Record<string, string | number>,
): string {
  const raw = lookup(key);

