"use client";

import * as React from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { Select } from "@/components/ui/Select";
import { Field } from "@/components/ui/Field";
import { Chip } from "@/components/ui/Chip";
import { Button } from "@/components/ui/Button";
import { TOPICS, LANGUAGES } from "@/lib/constants";
import { t } from "@/lib/i18n";

const PRICE_TIERS = [2000, 2500, 3000, 4000];

/**
 * Browse filters, v2: a flat editorial toolbar — no card box. Selects for
 * topic/language/price (labelled, ≥52px), the availability filter as a
 * tinted toggle chip (≥48px), all separated from the results by a hairline.
 */
export function BrowseFilters() {
  const router = useRouter();
  const params = useSearchParams();

  function update(key: string, value: string) {
    const next = new URLSearchParams(params.toString());
    if (value) next.set(key, value);
    else next.delete(key);
    router.push(`/browse?${next.toString()}`);
  }

  const availableOnly = params.get("available") === "1";
  const hasFilters = ["topic", "language", "available", "maxPrice"].some((k) =>
    params.has(k),
  );

  return (
    <section
      aria-label={t("browse.filtersHeading")}
      className="flex flex-wrap items-end gap-x-5 gap-y-4 border-b border-border pb-8"
    >
      <div className="w-56 max-sm:w-full">
        <Field label={t("browse.topicLabel")}>
          {(p) => (
            <Select
              {...p}
              value={params.get("topic") ?? ""}
              onChange={(e) => update("topic", e.target.value)}
            >
              <option value="">{t("browse.anyTopic")}</option>
              {TOPICS.map((topic) => (
                <option key={topic} value={topic}>
                  {topic}
                </option>
              ))}
            </Select>
          )}
        </Field>
      </div>

      <div className="w-48 max-sm:w-full">
        <Field label={t("browse.languageLabel")}>
          {(p) => (
            <Select
              {...p}
              value={params.get("language") ?? ""}
              onChange={(e) => update("language", e.target.value)}
            >
              <option value="">{t("browse.anyLanguage")}</option>
              {LANGUAGES.map((lang) => (
                <option key={lang} value={lang}>
                  {lang}
                </option>
              ))}
            </Select>
          )}
        </Field>
      </div>

      <div className="w-48 max-sm:w-full">
        <Field label={t("browse.priceLabel")}>
          {(p) => (
            <Select
              {...p}
              value={params.get("maxPrice") ?? ""}
              onChange={(e) => update("maxPrice", e.target.value)}
            >
              <option value="">{t("browse.anyPrice")}</option>
              {PRICE_TIERS.map((cents) => (
                <option key={cents} value={cents}>
                  {`$${cents / 100}`}
                </option>
              ))}
            </Select>
          )}
        </Field>
      </div>

      <div className="pb-0.5">
        <Chip
          selected={availableOnly}
          onClick={() => update("available", availableOnly ? "" : "1")}
        >
          {t("browse.availableNowLabel")}
        </Chip>
      </div>

      {hasFilters ? (
        <div className="pb-1.5">
          <Button variant="quiet" onClick={() => router.push("/browse")}>
            {t("browse.clearFilters")}
          </Button>
        </div>
      ) : null}
    </section>
  );
}

