import Link from "next/link";
import { ArrowRight, Star } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Avatar } from "@/components/ui/Avatar";
import { Tag } from "@/components/ui/Tag";
import { Availability } from "@/components/ui/Availability";
import { VoicePlayer } from "@/components/ui/VoicePlayer";
import { FavoriteButton } from "@/components/customer/FavoriteButton";
import { formatCents, formatRating } from "@/lib/format";
import { t } from "@/lib/i18n";
import { type PublicProvider } from "@/lib/supabase/types";

/**
 * Listener card — one of the few genuinely elevated surfaces (DESIGN_SPEC_V2
 * §4): borderless white tile that lifts on hover. Avatar carries the
 * availability arc ring (decorative — the Availability pill is the text
 * label), serif name + star rating in tabular numerals, the VoicePlayer
 * strip, up to three topic tags, then a hairline with serif tabular price
 * left and the primary profile CTA right, pinned to the bottom.
 */
export function ListenerCard({
  provider,
  audioUrl,
  canFavorite = false,
  isFavorite = false,
}: {
  provider: PublicProvider;
  audioUrl: string | null;
  canFavorite?: boolean;
  isFavorite?: boolean;
}) {
  return (
    <Card as="li" interactive className="flex flex-col gap-5">
      <div className="flex items-start gap-4">
        <Avatar
          name={provider.display_name}
          color={provider.avatar_color}
          size={64}
          available={provider.is_available_now}
        />
        <div className="flex min-w-0 flex-1 flex-col gap-1.5">
          <h2 className="text-h3">{provider.display_name}</h2>
          <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5">
            {provider.rating_count > 0 ? (
              <span className="flex items-center gap-1 text-base text-ink-soft">
                <Star
                  size={16}
                  strokeWidth={2}
                  aria-hidden="true"
                  className="fill-accent text-accent"
                />
                <span className="font-bold tabular-nums text-ink">
                  {formatRating(provider.rating_avg)}
                </span>
                <span className="tabular-nums">({provider.rating_count})</span>
              </span>
            ) : null}
            <Availability
              status={provider.is_available_now ? "available" : "scheduled"}
            />
          </div>
        </div>
        {canFavorite ? (
          <FavoriteButton
            providerId={provider.id}
            providerName={provider.display_name}
            initialFavorite={isFavorite}
          />
        ) : null}
      </div>

      <VoicePlayer
        name={provider.display_name}
        intro={provider.bio}
        audioUrl={audioUrl}
      />

      <ul className="flex flex-wrap gap-2">
        {provider.topics.slice(0, 3).map((topic) => (
          <li key={topic}>
            <Tag>{topic}</Tag>
          </li>
        ))}
      </ul>

      <div className="mt-auto flex items-end justify-between gap-3 border-t border-border pt-5">
        <p className="flex items-baseline gap-1.5">
          <span className="font-display text-[1.75rem] font-semibold leading-none tracking-[-0.015em] text-ink tabular-nums">
            {formatCents(provider.price_block_30_cents)}
          </span>
          <span className="text-sm font-bold text-ink-soft">
            {t("browse.perBlockCaption", { minutes: 30 })}
          </span>
        </p>
        <Link
          href={`/listeners/${provider.id}`}
          className="inline-flex min-h-12 items-center gap-2 whitespace-nowrap rounded-pill bg-primary px-6 text-base font-extrabold text-surface transition-colors duration-200 hover:bg-primary-dark"
        >
          {t("browse.viewProfile", { name: provider.display_name })}
          <ArrowRight size={18} strokeWidth={2} aria-hidden="true" />
        </Link>
      </div>
    </Card>
  );
}

