import Link from "next/link";
import { Suspense } from "react";
import { Button } from "@/components/ui/Button";
import { BrowseFilters } from "@/components/customer/BrowseFilters";
import { ListenerCard } from "@/components/customer/ListenerCard";
import { EmptyState } from "@/components/customer/EmptyState";
import { listApprovedProviders, listFavoriteIds } from "@/lib/db/queries";
import { getVoiceIntroSignedUrl } from "@/lib/storage";
import { getProfile } from "@/lib/auth";
import { t } from "@/lib/i18n";

export const metadata = { title: `${t("browse.title")} · ${t("app.name")}` };

export default async function BrowsePage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | undefined>>;
}) {
  const sp = await searchParams;
  const maxPrice = sp.maxPrice ? Number(sp.maxPrice) : undefined;

  const profile = await getProfile();
  const isCustomer = profile?.role === "customer";

  const [providers, favoriteIds] = await Promise.all([
    listApprovedProviders({
      topic: sp.topic || undefined,
      language: sp.language || undefined,
      availableNow: sp.available === "1" || undefined,
      maxPriceCents:
        typeof maxPrice === "number" && Number.isFinite(maxPrice)
          ? maxPrice
          : undefined,
    }),
    isCustomer ? listFavoriteIds(profile.id) : Promise.resolve([]),
  ]);
  const favoriteSet = new Set(favoriteIds);

  const withAudio = await Promise.all(
    providers.map(async (provider) => ({
      provider,
      audioUrl: await getVoiceIntroSignedUrl(provider.voice_intro_path),
    })),
  );

  return (
    <div className="flex flex-col gap-8 py-2">
      <header className="flex flex-col gap-3">
        <p className="kicker">{t("browse.kicker")}</p>
        <h1 className="text-display max-md:text-h1">{t("browse.title")}</h1>
        <p className="max-w-2xl text-lg text-ink-soft">{t("browse.subtitle")}</p>
      </header>

      <Suspense fallback={null}>
        <BrowseFilters />
      </Suspense>

      <p
        className="text-sm font-extrabold uppercase tracking-[0.12em] text-ink-soft tabular-nums"
        aria-live="polite"
      >
        {t("browse.resultsCount", { count: providers.length })}
      </p>

      {withAudio.length === 0 ? (
        <EmptyState
          sentence={t("browse.noResults")}
          action={
            <Link href="/browse" className="rounded-pill">
              <Button>{t("browse.clearFilters")}</Button>
            </Link>
          }
        />
      ) : (
        <ul className="grid grid-cols-1 gap-6 md:grid-cols-2 xl:grid-cols-3">
          {withAudio.map(({ provider, audioUrl }) => (
            <ListenerCard
              key={provider.id}
              provider={provider}
              audioUrl={audioUrl}
              canFavorite={isCustomer}
              isFavorite={favoriteSet.has(provider.id)}
            />
          ))}
        </ul>
      )}
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { ChevronLeft, Phone, CalendarDays, Star } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Tag } from "@/components/ui/Tag";
import { Avatar } from "@/components/ui/Avatar";
import { Availability } from "@/components/ui/Availability";
import { VoicePlayer } from "@/components/ui/VoicePlayer";
import { FavoriteButton } from "@/components/customer/FavoriteButton";
import {
  getApprovedProvider,
  listProviderReviews,
  listFavoriteIds,
} from "@/lib/db/queries";
import { getVoiceIntroSignedUrl } from "@/lib/storage";
import { getProfile } from "@/lib/auth";
import { formatCents, formatRating } from "@/lib/format";
import { t } from "@/lib/i18n";
import { type BlockMinutes } from "@/lib/pricing";

const BLOCKS: BlockMinutes[] = [15, 30, 45];

export default async function ListenerProfilePage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  const provider = await getApprovedProvider(id);
  if (!provider) notFound();

  const profile = await getProfile();
  const isCustomer = profile?.role === "customer";
  const [reviews, audioUrl, favoriteIds] = await Promise.all([
    listProviderReviews(id),
    getVoiceIntroSignedUrl(provider.voice_intro_path),
    isCustomer ? listFavoriteIds(profile.id) : Promise.resolve([]),
  ]);
  const isFavorite = favoriteIds.includes(id);

  const prices: Record<BlockMinutes, number> = {
    15: provider.price_block_15_cents,
    30: provider.price_block_30_cents,
    45: provider.price_block_45_cents,
  };

  return (
    <div className="flex flex-col gap-10 py-2">
      <Link
        href="/browse"
        className="inline-flex min-h-12 items-center gap-1.5 self-start rounded-sm text-base font-bold text-primary"
      >
        <ChevronLeft size={20} strokeWidth={2} aria-hidden="true" />
        {t("listener.backToBrowse")}
      </Link>

      {/* Editorial header */}
      <header className="flex flex-wrap items-center gap-x-8 gap-y-6">
        <Avatar
          name={provider.display_name}
          color={provider.avatar_color}
          size={112}
          available={provider.is_available_now}
        />
        <div className="flex min-w-0 flex-1 flex-col gap-3">
          <p className="kicker">{t("listener.kicker")}</p>
          <h1 className="text-display max-md:text-h1">
            {provider.display_name}
          </h1>
          <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
            {provider.rating_count > 0 ? (
              <span className="flex items-center gap-1.5 text-base text-ink-soft">
                <Star
                  size={18}
                  strokeWidth={2}
                  aria-hidden="true"
                  className="fill-accent text-accent"
                />
                <span className="font-bold tabular-nums text-ink">
                  {formatRating(provider.rating_avg)}
                </span>
                <span className="tabular-nums">({provider.rating_count})</span>
              </span>
            ) : null}
            <Availability
              status={provider.is_available_now ? "available" : "scheduled"}
            />
            {isCustomer ? (
              <FavoriteButton
                providerId={provider.id}
                providerName={provider.display_name}
                initialFavorite={isFavorite}
              />
            ) : null}
          </div>
        </div>
      </header>

      <div className="grid items-start gap-x-14 gap-y-10 lg:grid-cols-[minmax(0,1fr)_22.5rem]">
        <div className="flex min-w-0 flex-col gap-10">
          {/* The signature moment: hear the voice first */}
          <VoicePlayer
            name={provider.display_name}
            intro={provider.bio}
            big
            audioUrl={audioUrl}
          />

          <section className="flex flex-col gap-4 border-t border-border pt-8">
            <h2 className="text-h3">{t("listener.topicsHeading")}</h2>
            <ul className="flex flex-wrap gap-2">
              {provider.topics.map((topic) => (
                <li key={topic}>
                  <Tag>{topic}</Tag>
                </li>
              ))}
            </ul>
          </section>

          <section className="flex flex-col gap-3 border-t border-border pt-8">
            <h2 className="text-h3">{t("listener.languagesHeading")}</h2>
            <p className="text-base text-ink">
              {provider.languages.join(", ")}
            </p>
          </section>

          <section className="flex flex-col gap-4 border-t border-border pt-8">
            <h2 className="text-h2">{t("listener.reviewsHeading")}</h2>
            {reviews.length === 0 ? (
              <p className="font-display text-lg italic text-ink-soft">
                {t("listener.noReviews")}
              </p>
            ) : (
              <ul className="flex flex-col divide-y divide-border">
                {reviews.map((review) => (
                  <li key={review.id} className="flex flex-col gap-2.5 py-6">
                    <p className="max-w-[65ch] font-display text-lg leading-body text-ink">
                      {review.comment}
                    </p>
                    <p className="flex items-center gap-1.5 text-sm font-bold text-ink-soft">
                      <Star
                        size={15}
                        strokeWidth={2}
                        aria-hidden="true"
                        className="fill-accent text-accent"
                      />
                      <span className="tabular-nums">
                        {t("summary.starLabel", { n: review.rating })}
                      </span>
                    </p>
                  </li>
                ))}
              </ul>
            )}
          </section>
        </div>

        {/* Booking column — sticky on desktop, stacked on mobile */}
        <aside className="w-full lg:sticky lg:top-8">
          <Card as="section" className="flex flex-col gap-6 p-7">
            <h2 className="text-h3">{t("listener.bookHeading")}</h2>
            <ul className="grid grid-cols-3 divide-x divide-border border-y border-border">
              {BLOCKS.map((minutes) => (
                <li
                  key={minutes}
