"use client";

import * as React from "react";
import { CircleAlert, CreditCard, ShieldCheck, Check } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Field, Input } from "@/components/ui/Field";
import { createBooking } from "@/app/(customer)/actions";
import { formatCents } from "@/lib/format";
import { t } from "@/lib/i18n";
import { donationPresetsCents, type BlockMinutes } from "@/lib/pricing";

export interface BookingProvider {
  id: string;
  displayName: string;
  prices: Record<BlockMinutes, number>;
  overagePerMinCents: number;
}

const BLOCKS: BlockMinutes[] = [15, 30, 45];

/**
 * Selectable tile, v2 (DESIGN_SPEC_V2 §6 Booking): white elevated tile;
 * selected = solid teal fill + check icon (never color alone). The radio
 * input stays in the tree (sr-only) so tiles are fully keyboard operable,
 * with the focus ring drawn on the tile via :has(:focus-visible).
 */
const TILE =
  "flex cursor-pointer flex-col rounded-tile p-5 text-left transition-[background-color,color,box-shadow] duration-200 has-[:focus-visible]:shadow-[0_0_0_3px_var(--color-focus)]";
const TILE_ON = "bg-primary text-surface";
const TILE_OFF = "bg-surface shadow-sm hover:bg-primary-tint";

export function BookingForm({
  provider,
  defaultMode,
}: {
  provider: BookingProvider;
  defaultMode: "now" | "scheduled";
}) {
  const [block, setBlock] = React.useState<BlockMinutes>(30);
  const [mode, setMode] = React.useState<"now" | "scheduled">(defaultMode);
  const [scheduledAt, setScheduledAt] = React.useState("");
  // The donation: a preset (cents) or "custom" with a free-typed dollar amount.
  const [selection, setSelection] = React.useState<number | "custom">(
    provider.prices[30],
  );
  const [customDollars, setCustomDollars] = React.useState("");
  const [submitting, setSubmitting] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = React.useState<Record<string, string>>({});

  const floorCents = provider.prices[block];
  const presets = donationPresetsCents(floorCents);

  function changeBlock(minutes: BlockMinutes) {
    setBlock(minutes);
    // Re-anchor the donation to the new block's suggested amount.
    setSelection(provider.prices[minutes]);
    setCustomDollars("");
  }

  const customCents = Math.round((parseFloat(customDollars) || 0) * 100);
  const customValid = customCents >= floorCents;
  const donationValid = selection !== "custom" || customValid;
  const donationCents =
    selection === "custom"
      ? customValid
        ? customCents
        : floorCents
      : selection;

  async function onConfirm() {
    setSubmitting(true);
    setError(null);
    setFieldErrors({});
    const res = await createBooking({
      providerId: provider.id,
      blockMinutes: block,
      startMode: mode,
      scheduledAt:
        mode === "scheduled" && scheduledAt
          ? new Date(scheduledAt).toISOString()
          : undefined,
      donationCents,
    });
    // Success redirects; only errors return.
    if (res?.error) {
      setError(res.error);
      setFieldErrors(res.fieldErrors ?? {});
      setSubmitting(false);
    }
  }

  return (
    <div className="flex flex-col gap-9">
      {error ? (
        <p
          role="alert"
          className="flex items-start gap-2 rounded-card border-l-4 border-alert bg-alert-tint px-4 py-3 text-base"
        >
          <CircleAlert size={20} aria-hidden="true" className="mt-0.5 text-alert" />
          {error}
        </p>
      ) : null}

      <fieldset className="flex flex-col gap-4">
        <legend className="mb-4 text-h3">{t("booking.chooseLength")}</legend>
        <div className="grid grid-cols-3 gap-4 max-sm:grid-cols-1">
          {BLOCKS.map((minutes) => {
            const selected = block === minutes;
            return (
              <label
                key={minutes}
                className={[TILE, "items-center gap-2 py-6 text-center", selected ? TILE_ON : TILE_OFF].join(" ")}
              >
                <input
                  type="radio"
                  name="block"
                  value={minutes}
                  checked={selected}
                  onChange={() => changeBlock(minutes)}
                  className="sr-only"
                />
                <span
                  className={[
                    "flex items-center gap-1.5 text-sm font-extrabold uppercase tracking-[0.1em]",
                    selected ? "text-surface" : "text-ink-soft",
                  ].join(" ")}
                >
                  {selected ? (
                    <Check size={16} strokeWidth={2.5} aria-hidden="true" />
                  ) : null}
                  {t("booking.minutes", { minutes })}
                </span>
                <span className="font-display text-[2rem] font-semibold leading-none tabular-nums">
                  {formatCents(provider.prices[minutes])}
                </span>
              </label>
            );
          })}
        </div>
      </fieldset>

      <fieldset className="flex flex-col gap-4">
        <legend className="mb-4 text-h3">{t("booking.donationHeading")}</legend>
        <div className="grid grid-cols-4 gap-3 max-sm:grid-cols-2">
          {presets.map((cents, i) => {
            const selected = selection === cents;
            return (
              <label
                key={cents}
                className={[TILE, "items-start gap-1 p-4", selected ? TILE_ON : TILE_OFF].join(" ")}
              >
                <input
                  type="radio"
                  name="donation"
                  checked={selected}
                  onChange={() => {
                    setSelection(cents);
                    setCustomDollars("");
                  }}
                  className="sr-only"
                />
                <span className="flex items-center gap-1.5 font-display text-[1.375rem] font-semibold leading-none tabular-nums">
                  {selected ? (
                    <Check size={16} strokeWidth={2.5} aria-hidden="true" />
                  ) : null}
                  {formatCents(cents)}
                </span>
                {i === 0 ? (
                  <span
                    className={[
                      "text-sm font-bold",
                      selected ? "text-surface" : "text-primary-dark",
                    ].join(" ")}
                  >
                    {t("booking.donationSuggested")}
                  </span>
                ) : null}
              </label>
            );
          })}
          <label
            className={[
              TILE,
              "items-start justify-center p-4",
              selection === "custom" ? TILE_ON : TILE_OFF,
            ].join(" ")}
          >
            <input
              type="radio"
              name="donation"
              checked={selection === "custom"}
              onChange={() => setSelection("custom")}
              className="sr-only"
            />
            <span className="flex items-center gap-1.5 text-lg font-bold">
              {selection === "custom" ? (
                <Check size={16} strokeWidth={2.5} aria-hidden="true" />
              ) : null}
              {t("booking.donationCustom")}
            </span>
          </label>
        </div>
        {selection === "custom" ? (
          <Field
            label={t("booking.donationCustomLabel")}
            error={
              customDollars && !customValid
                ? t("booking.donationBelowMin", { min: formatCents(floorCents) })
                : undefined
            }
          >
            {(p) => (
              <Input
                {...p}
                type="number"
                min={floorCents / 100}
                step="1"
                inputMode="decimal"
                value={customDollars}
                onChange={(e) => setCustomDollars(e.target.value)}
              />
            )}
          </Field>
        ) : null}
        <p className="text-sm text-ink-soft">
          {t("booking.donationMinHint", { min: formatCents(floorCents) })}
        </p>
      </fieldset>

      <fieldset className="flex flex-col gap-4">
        <legend className="mb-4 text-h3">{t("booking.startHeading")}</legend>
        <div className="flex flex-col gap-2.5">
          {(["now", "scheduled"] as const).map((value) => (
            <label
              key={value}
              className="flex min-h-12 cursor-pointer items-center gap-3 rounded-tile bg-surface px-5 py-3.5 text-base font-bold text-ink shadow-sm transition-colors duration-200 hover:bg-primary-tint has-[:checked]:bg-primary-tint has-[:focus-visible]:shadow-[0_0_0_3px_var(--color-focus)]"
            >
              <input
                type="radio"
                name="mode"
                value={value}
                checked={mode === value}
                onChange={() => setMode(value)}
                className="size-5 accent-[var(--color-primary)]"
              />
              {value === "now" ? t("booking.startNow") : t("booking.startScheduled")}
            </label>
          ))}
        </div>
        {mode === "scheduled" ? (
          <Field label={t("booking.scheduledAtLabel")} error={fieldErrors.scheduledAt} required>
            {(p) => (
              <Input
                {...p}
                type="datetime-local"
                value={scheduledAt}
                onChange={(e) => setScheduledAt(e.target.value)}
              />
            )}
          </Field>
        ) : null}
      </fieldset>

      {/* Flat editorial summary — hairlines, serif tabular total */}
      <section className="flex flex-col gap-2 border-t border-border pt-6">
        <h2 className="text-h3">{t("booking.summaryHeading")}</h2>
        <p className="text-base text-ink">
          {t("booking.summaryBlock", { minutes: block })}
        </p>
        <p className="text-sm text-ink-soft">
          {t("booking.summaryOverage", {
            price: formatCents(provider.overagePerMinCents),
          })}
        </p>
        <div className="mt-3 flex flex-wrap items-baseline justify-between gap-3 border-t border-border pt-4">
          <span className="text-lg font-bold text-ink">
            {t("booking.summaryTotal")}
          </span>
          <span className="font-display text-h2 font-semibold leading-none text-ink tabular-nums">
            {formatCents(donationCents)}
          </span>
        </div>
      </section>

      <p className="flex items-center gap-3 border-t border-border pt-5 text-base text-ink">
        <CreditCard size={22} aria-hidden="true" className="flex-none text-ink-soft" />
        {t("booking.paymentMock")}
      </p>

      <p className="flex items-start gap-2 text-base text-ink-soft">
        <ShieldCheck size={20} aria-hidden="true" className="mt-0.5 flex-none text-primary" />
        {t("booking.reassurance")}
      </p>

      <Button
        full
        onClick={onConfirm}
        disabled={
          submitting ||
          !donationValid ||
          (mode === "scheduled" && !scheduledAt)
        }
      >
        {submitting ? t("booking.confirming") : t("booking.confirm")}
      </Button>
    </div>
  );
}

import Link from "next/link";
import {
  CircleCheck,
  Phone,
  Settings,
  Download,
  Clock,
  RotateCcw,
  XCircle,
  type LucideIcon,
} from "lucide-react";
import { Button } from "@/components/ui/Button";
import { StatusBadge } from "@/components/ui/StatusBadge";
import { FavoriteListeners } from "@/components/customer/FavoriteListeners";
import { UpcomingBookings } from "@/components/customer/UpcomingBookings";
import { PastSessionsTable } from "@/components/customer/PastSessionsTable";
import { requireRole } from "@/lib/auth";
import {
  listCustomerBookings,
  listCustomerCompletedSessions,
  listCustomerPayments,
  listCustomerReviews,
  listFavoriteProviders,
  getApprovedProvidersByIds,
} from "@/lib/db/queries";
import { getVoiceIntroSignedUrl } from "@/lib/storage";
import { formatCents } from "@/lib/format";
import { shortDate, durationLabel } from "@/lib/time";
import { t } from "@/lib/i18n";

export const metadata = { title: `${t("account.title")} · ${t("app.name")}` };

export default async function AccountPage({
  searchParams,
}: {
  searchParams: Promise<{ booked?: string }>;
}) {
  const profile = await requireRole("customer");
  const { booked } = await searchParams;

  const [bookings, sessions, payments, reviews, favorites] = await Promise.all([
    listCustomerBookings(profile.id),
    listCustomerCompletedSessions(profile.id),
    listCustomerPayments(profile.id),
    listCustomerReviews(profile.id),
    listFavoriteProviders(profile.id),
  ]);

  // Resolve listener names for bookings + sessions.
  const providerIds = Array.from(
    new Set([
      ...bookings.map((b) => b.provider_id),
      ...sessions.map((s) => s.provider_id),
    ]),
  );
  const providersById = await getApprovedProvidersByIds(providerIds);
  const nameFor = (id: string) => providersById.get(id)?.display_name ?? "—";

  const favoritesWithAudio = await Promise.all(
    favorites.map(async (provider) => ({
      provider,
      audioUrl: await getVoiceIntroSignedUrl(provider.voice_intro_path),
    })),
  );

  // Sort by actual chronology: in-progress first, then "now" bookings, then
  // scheduled by their time — so "Next session" is the soonest, not the latest
  // created.
  const sortKey = (b: (typeof bookings)[number]) =>
    b.status === "in_progress"
      ? 0
      : b.scheduled_at
        ? new Date(b.scheduled_at).getTime()
        : 1; // a "now" booking is imminent
  const upcoming = bookings
    .filter((b) => b.status === "confirmed" || b.status === "in_progress")
    .sort((a, b) => sortKey(a) - sortKey(b))
    .map((b) => ({
      id: b.id,
      providerName: nameFor(b.provider_id),
      blockMinutes: b.block_minutes,
      status: b.status as "confirmed" | "in_progress",
      whenLabel: b.scheduled_at
        ? shortDate(b.scheduled_at)
        : t("account.talkNow"),
    }));

  const next = upcoming[0];

  const reviewedSessionIds = new Set(
    reviews.map((r) => r.session_id).filter(Boolean),
  );
  // Receipts only make sense for completed sessions; an authorized hold on an
  // upcoming booking has no receipt yet.
  const completedBookingIds = new Set(sessions.map((s) => s.booking_id));
  const PAY_STATUS: Record<
    string,
    { labelKey: "account.payAuthorized" | "account.payCaptured" | "account.payRefunded" | "account.payFailed"; tone: "success" | "neutral" | "alert"; icon: LucideIcon }
  > = {
    authorized: { labelKey: "account.payAuthorized", tone: "neutral", icon: Clock },
    captured: { labelKey: "account.payCaptured", tone: "success", icon: CircleCheck },
    refunded: { labelKey: "account.payRefunded", tone: "neutral", icon: RotateCcw },
    failed: { labelKey: "account.payFailed", tone: "alert", icon: XCircle },
  };
  const receipts = payments
    .filter((p) => completedBookingIds.has(p.booking_id))
    .map((p) => {
      const booking = bookings.find((b) => b.id === p.booking_id);
      const name = booking ? nameFor(booking.provider_id) : "—";
      return {
        id: p.id,
        bookingId: p.booking_id,
        amountCents: p.amount_cents,
        status: p.status,
        dateLabel: shortDate(p.created_at),
        listenerName: name,
      };
    });
  const pastRows = sessions.map((s) => ({
    id: s.id,
    bookingId: s.booking_id,
    dateLabel: shortDate(s.ended_at),
    endedAtMs: s.ended_at ? new Date(s.ended_at).getTime() : 0,
    listenerName: nameFor(s.provider_id),
    durationLabel: durationLabel(s.elapsed_seconds),
    amountCents: s.total_price_cents,
    hasReview: reviewedSessionIds.has(s.id),
  }));

  return (
    <div className="flex flex-col gap-12 py-2 max-md:gap-9">
      <header className="flex flex-wrap items-end justify-between gap-x-6 gap-y-4">
        <div className="flex flex-col gap-3">
          <p className="kicker">{t("account.kicker")}</p>
          <h1 className="text-display max-md:text-h1">{t("account.title")}</h1>
          <p className="max-w-2xl text-lg text-ink-soft">
            {t("account.subtitle")}
          </p>
        </div>
        <Link href="/account/settings" className="rounded-pill">
          <Button variant="ghost" icon={Settings}>
            {t("account.settingsLink")}
          </Button>
        </Link>
      </header>

      {booked ? (
        <p
          role="status"
          className="flex items-center gap-3 rounded-tile bg-success-tint px-5 py-4 text-base font-bold text-ink"
        >
          <CircleCheck
            size={22}
            aria-hidden="true"
