"use client";

import * as React from "react";
import { useTransition } from "react";
import Link from "next/link";
import { Phone, CalendarClock, X, Check } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Field, Input } from "@/components/ui/Field";
import { StatusBadge } from "@/components/ui/StatusBadge";
import { cancelBooking, rescheduleBooking } from "@/app/(customer)/account/actions";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";

export interface UpcomingItem {
  id: string;
  providerName: string;
  blockMinutes: number;
  status: "confirmed" | "in_progress";
  whenLabel: string;
}

/**
 * Upcoming bookings, v2: flat hairline-separated list rows (DESIGN_SPEC_V2
 * §6 Account) — no card boxes. Join is the primary action; cancel keeps its
 * two-step confirmation.
 */
export function UpcomingBookings({ items }: { items: UpcomingItem[] }) {
  const [pending, startTransition] = useTransition();
  const [rescheduleId, setRescheduleId] = React.useState<string | null>(null);
  const [confirmId, setConfirmId] = React.useState<string | null>(null);
  const [newTime, setNewTime] = React.useState("");
  const { announce, toast } = useToast();

  function cancel(id: string) {
    setConfirmId(null);
    startTransition(async () => {
      const res = await cancelBooking(id);
      if (!res.ok) {
        toast(res.error ?? t("booking.error"), "alert");
        return;
      }
      announce(
        res.released ? t("account.cancelledRefund") : t("account.cancelledCharged"),
        true,
      );
    });
  }

  function saveReschedule(id: string) {
    if (!newTime) return;
    startTransition(async () => {
      const res = await rescheduleBooking({
        bookingId: id,
        scheduledAt: new Date(newTime).toISOString(),
      });
      if (!res.ok) {
        toast(res.error ?? t("booking.error"), "alert");
        return;
      }
      setRescheduleId(null);
      setNewTime("");
      announce(t("account.rescheduled"), true);
    });
  }

  if (items.length === 0) {
    return (
      <p className="font-display text-lg italic text-ink-soft">
        {t("account.upcomingNone")}
      </p>
    );
  }

  return (
    <ul className="flex flex-col divide-y divide-border border-y border-border">
      {items.map((item) => (
        <li key={item.id} className="flex flex-col gap-3 py-5">
          <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-3">
            <div className="flex flex-wrap items-center gap-3">
              <StatusBadge tone="info" icon={CalendarClock}>
                {item.whenLabel}
              </StatusBadge>
              <span className="text-base font-bold text-ink">
                {t("account.bookingSummary", {
                  name: item.providerName,
                  minutes: item.blockMinutes,
                })}
              </span>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              <Link href={`/session/${item.id}`} className="rounded-pill">
                <Button icon={Phone}>{t("account.join")}</Button>
              </Link>
              {/* Reschedule/Cancel only apply to a not-yet-started booking. */}
              {item.status === "confirmed" ? (
                <>
                  <Button
                    variant="ghost"
                    icon={CalendarClock}
                    onClick={() => {
                      setConfirmId(null);
                      setRescheduleId(rescheduleId === item.id ? null : item.id);
                    }}
                  >
                    {t("account.reschedule")}
                  </Button>
                  <Button
                    variant="ghost"
                    icon={X}
                    onClick={() => {
                      setRescheduleId(null);
                      setConfirmId(item.id);
                    }}
                    disabled={pending}
                  >
                    {t("account.cancel")}
                  </Button>
                </>
              ) : null}
            </div>
          </div>

          {confirmId === item.id ? (
            <div
              role="group"
              aria-label={t("account.cancelConfirm")}
              className="flex flex-wrap items-center gap-3 border-t border-border pt-3"
            >
              <span className="text-base font-bold text-ink">
                {t("account.cancelConfirm")}
              </span>
              <Button
                variant="danger"
                icon={X}
                onClick={() => cancel(item.id)}
                disabled={pending}
              >
                {t("account.confirmCancel")}
              </Button>
              <Button variant="ghost" onClick={() => setConfirmId(null)}>
                {t("account.keepBooking")}
              </Button>
            </div>
          ) : null}

          {rescheduleId === item.id ? (
            <div className="flex flex-wrap items-end gap-3 border-t border-border pt-3">
              <Field label={t("account.rescheduleHeading")}>
                {(p) => (
                  <Input
                    {...p}
                    type="datetime-local"
                    value={newTime}
                    onChange={(e) => setNewTime(e.target.value)}
                  />
                )}
              </Field>
              <Button
                icon={Check}
                onClick={() => saveReschedule(item.id)}
                disabled={pending || !newTime}
              >
                {t("account.rescheduleSave")}
              </Button>
            </div>
          ) : null}
        </li>
      ))}
    </ul>
  );
}

