"use client";

import * as React from "react";
import { Mic, MicOff, Captions, PhoneOff } from "lucide-react";
import { Avatar } from "@/components/ui/Avatar";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";

function fmt(totalSeconds: number): string {
  const m = Math.floor(totalSeconds / 60);
  const s = totalSeconds % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

/** Animated speaking bars; static when muted and under reduced motion (CSS). */
function CallWaveform({ active }: { active: boolean }) {
  const bars = [14, 28, 20, 34, 16, 30, 24, 38, 18, 26];
  return (
    <span aria-hidden="true" className="flex h-10 items-center gap-1.5">
      {bars.map((h, i) => (
        <span
          key={i}
          className="w-1.5 rounded-full bg-accent"
          style={{
            height: active ? h : 6,
            // Delay folded into the shorthand — don't mix `animation` with a
            // separate `animationDelay` (React warns on conflicting updates).
            animation: active
              ? `wf 0.9s var(--ease-warm) ${i * 0.07}s infinite alternate`
              : "none",
          }}
        />
      ))}
    </span>
  );
}

/**
 * Breathing concentric listening arcs behind the timer — the logo motif at
 * stage scale (DESIGN_SPEC_V2 §1/§6). Pure CSS animation (4s), so the global
 * reduced-motion kill switch freezes it. Strictly decorative.
 */
function BreathingArcs() {
  return (
    <div aria-hidden="true" className="absolute inset-0 -z-10 grid place-items-center overflow-hidden">
      <style>{`@keyframes call-breathe { from { transform: scale(0.96); opacity: 0.55; } to { transform: scale(1.03); opacity: 1; } }`}</style>
      {[300, 480, 660, 840].map((d, i) => (
        <span
          key={d}
          className={[
            "absolute rounded-full border",
            i === 2 ? "border-accent/25" : "border-surface/10",
          ].join(" ")}
          style={{
            width: d,
            height: d,
            animation: `call-breathe 4s var(--ease-warm) ${i * 0.5}s infinite alternate`,
          }}
        />
      ))}
    </div>
  );
}

export interface CallStageProps {
  name: string;
  avatarColor: string;
  /** Called with the elapsed seconds (the timer is the source of truth). */
  onEnd: (elapsedSeconds: number) => Promise<void>;
  endLabel: string;
}

/**
 * The call stage, v2: an immersive warm-ink band with breathing arcs behind
 * an oversized serif tabular timer (DESIGN_SPEC_V2 §6). Controls are
 * oversized, always labelled, ≥48px, with state via aria-pressed + label —
 * never color alone.
 */
export function CallStage({ name, avatarColor, onEnd, endLabel }: CallStageProps) {
  const { announce } = useToast();
  const [elapsed, setElapsed] = React.useState(0);
  const [muted, setMuted] = React.useState(false);
  const [captionsOn, setCaptionsOn] = React.useState(false);
  const [ending, setEnding] = React.useState(false);
  const elapsedRef = React.useRef(0);

  React.useEffect(() => {
    announce(t("session.connectedAnnounce"), true);
    const id = window.setInterval(() => {
      elapsedRef.current += 1;
      setElapsed(elapsedRef.current);
    }, 1000);
    return () => window.clearInterval(id);
  }, [announce]);

  async function end() {
    setEnding(true);
    announce(t("session.endedAnnounce"), true);
    await onEnd(elapsedRef.current);
  }

  const controlBase =
    "inline-flex min-h-14 items-center gap-2.5 rounded-pill px-7 text-base font-extrabold transition-[background-color,transform] duration-200 active:scale-[0.98]";

  return (
    <div className="relative isolate flex min-h-[72dvh] w-full flex-col items-center justify-center gap-9 overflow-hidden rounded-tile bg-ink px-6 py-16 text-surface max-md:gap-7 max-md:px-4 max-md:py-10">
      <BreathingArcs />

      <div className="flex flex-col items-center gap-4">
        <Avatar name={name} color={avatarColor} size={104} />
        <h1 className="text-h2 text-surface">{name}</h1>
        <p className="flex items-center gap-2.5 text-base font-bold text-surface/80">
          <CallWaveform active={!muted} />
          {muted ? t("session.muted") : t("session.speaking")}
        </p>
      </div>

      <p
        className="numeral text-surface"
        role="timer"
        aria-label={t("session.timerLabel")}
      >
        {fmt(elapsed)}
      </p>

      {captionsOn ? (
        <p
          aria-live="polite"
          className="w-full max-w-xl rounded-tile bg-surface/10 p-5 text-base leading-body text-surface"
        >
          {t("session.captionsSample")}
        </p>
      ) : null}

      <div className="flex w-full max-w-2xl flex-wrap items-center justify-center gap-3 border-t border-surface/15 pt-9 max-md:pt-6">
        <button
          type="button"
          onClick={() => setMuted((m) => !m)}
          aria-pressed={muted}
          className={[
            controlBase,
            "border border-surface/40 text-surface hover:bg-surface/10 aria-pressed:bg-surface/15",
          ].join(" ")}
        >
          {muted ? (
            <MicOff size={22} strokeWidth={2} aria-hidden="true" />
          ) : (
            <Mic size={22} strokeWidth={2} aria-hidden="true" />
          )}
          {muted ? t("session.unmute") : t("session.mute")}
        </button>

        <button
          type="button"
          onClick={() => setCaptionsOn((c) => !c)}
          aria-pressed={captionsOn}
          className={[
            controlBase,
            "border border-surface/40 text-surface hover:bg-surface/10 aria-pressed:bg-surface/15",
          ].join(" ")}
        >
          <Captions size={22} strokeWidth={2} aria-hidden="true" />
          {captionsOn ? t("session.captionsOn") : t("session.captionsOff")}
        </button>

        <button
          type="button"
          onClick={end}
          disabled={ending}
          className={[
            controlBase,
            "bg-alert px-8 text-surface hover:brightness-95 disabled:opacity-60 disabled:active:scale-100",
          ].join(" ")}
        >
          <PhoneOff size={22} strokeWidth={2} aria-hidden="true" />
          {ending ? t("session.ending") : endLabel}
        </button>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { useRouter } from "next/navigation";
import { Phone, Mic } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Avatar } from "@/components/ui/Avatar";
import { CallStage } from "@/components/session/CallStage";
import { startSession, endSession } from "@/app/(customer)/session/actions";
import { t } from "@/lib/i18n";

/**
 * Customer session flow. Pre-call: a calm, flat editorial screen on cream —
 * no card box, just the listener, a breathing cue, and two clear paths.
 * In-call: the immersive ink CallStage.
 */
export function SessionFlow({
  bookingId,
  name,
  avatarColor,
}: {
  bookingId: string;
  name: string;
  avatarColor: string;
}) {
  const router = useRouter();
  const [phase, setPhase] = React.useState<"precall" | "incall">("precall");
  const [joining, setJoining] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  async function join() {
    setJoining(true);
    setError(null);
    const res = await startSession(bookingId);
    if (res.error) {
      setError(res.error);
      setJoining(false);
      return;
    }
    setPhase("incall");
  }

  if (phase === "incall") {
    return (
      <CallStage
        name={name}
        avatarColor={avatarColor}
        endLabel={t("session.end")}
        onEnd={async (elapsed) => {
          await endSession(bookingId, elapsed);
          router.push(`/session/${bookingId}/summary`);
        }}
      />
    );
  }

  return (
    <div className="mx-auto flex w-full max-w-xl flex-col items-center gap-7 py-12 text-center max-md:py-6">
      <Avatar name={name} color={avatarColor} size={112} />
      <span aria-hidden="true" className="flex items-center gap-2">
        {[0, 1, 2].map((i) => (
          <span
            key={i}
            className="size-2.5 rounded-pill bg-primary"
            style={{
              animation: `wf 0.9s var(--ease-warm) ${i * 0.15}s infinite alternate`,
            }}
          />
        ))}
      </span>
      <div className="flex flex-col items-center gap-3">
        <p className="kicker">{t("session.kicker")}</p>
        <h1 className="text-h1">{t("session.connectingTitle", { name })}</h1>
        <p className="max-w-md text-lg text-ink-soft">
          {t("session.connectingHelp")}
        </p>
      </div>
      <p className="flex items-center gap-2 text-base font-bold text-success">
        <Mic size={18} strokeWidth={2} aria-hidden="true" />
        {t("session.micCheck")}
      </p>

      {error ? (
        <p role="alert" className="text-base font-semibold text-alert">
          {error}
        </p>
      ) : null}

      <div className="flex w-full max-w-sm flex-col gap-3">
        <Button full icon={Phone} onClick={join} disabled={joining}>
          {joining ? t("ui.loading") : t("session.join")}
        </Button>
        <Button full variant="ghost" onClick={() => router.push("/account")}>
          {t("session.cancel")}
        </Button>
      </div>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { CircleCheck } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { RatingTipForm } from "@/components/customer/RatingTipForm";
import { requireRole } from "@/lib/auth";
import {
  getBooking,
  getSessionByBooking,
  getApprovedProvider,
  getReviewForSession,
} from "@/lib/db/queries";
import { formatCents } from "@/lib/format";
import { t } from "@/lib/i18n";

function fmtDuration(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

export default async function SessionSummaryPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  await requireRole("customer");
  const { id } = await params;
  const [booking, session] = await Promise.all([
    getBooking(id),
    getSessionByBooking(id),
  ]);
  if (!booking || !session) notFound();
  const [provider, review] = await Promise.all([
    getApprovedProvider(booking.provider_id),
    getReviewForSession(session.id),
  ]);

  const name = provider?.display_name ?? "your listener";

  return (
    <div className="mx-auto flex w-full max-w-xl flex-col gap-10 py-2 max-md:gap-8">
      <header className="flex flex-col gap-3">
        <p className="kicker">{t("summary.kicker")}</p>
        <h1 className="text-h1">{t("summary.title", { name })}</h1>
      </header>

      {review ? (
        <section
          role="status"
          className="flex items-start gap-3 rounded-tile bg-success-tint px-5 py-5"
        >
          <CircleCheck
            size={22}
            aria-hidden="true"
            className="mt-0.5 flex-none text-success-strong"
          />
          <div>
            <h2 className="text-h3">{t("summary.thankYouHeading")}</h2>
            <p className="mt-1 text-base text-ink-soft">
              {t("summary.thankYouBody", { name })}
            </p>
          </div>
        </section>
      ) : (
        <section className="border-t border-border pt-8">
          <RatingTipForm sessionId={session.id} providerId={booking.provider_id} />
        </section>
      )}

      {/* Flat receipt — hairline rows, serif tabular numerals */}
      <section className="flex flex-col gap-4 border-t border-border pt-8">
        <h2 className="text-h3">{t("summary.receiptHeading")}</h2>
        <dl className="flex flex-col divide-y divide-border">
          <div className="flex items-center justify-between py-3 text-base">
            <dt className="text-ink-soft">{t("summary.durationLabel")}</dt>
            <dd className="font-bold text-ink tabular-nums">
              {fmtDuration(session.elapsed_seconds)}
            </dd>
          </div>
          <div className="flex items-center justify-between py-3 text-base">
            <dt className="text-ink-soft">{t("summary.blockLabel")}</dt>
            <dd className="font-bold text-ink tabular-nums">
              {t("summary.minutesValue", { minutes: session.block_minutes })}
            </dd>
          </div>
          {session.overage_minutes > 0 ? (
            <div className="flex items-center justify-between py-3 text-base">
              <dt className="text-ink-soft">{t("summary.overageLabel")}</dt>
              <dd className="font-bold text-ink tabular-nums">
                {t("summary.minutesValue", { minutes: session.overage_minutes })}
              </dd>
            </div>
          ) : null}
          <div className="flex items-baseline justify-between gap-3 py-4">
            <dt className="text-lg font-bold text-ink">
              {t("summary.totalLabel")}
            </dt>
            <dd className="font-display text-h2 font-semibold leading-none text-ink tabular-nums">
              {formatCents(session.total_price_cents)}
            </dd>
          </div>
        </dl>
      </section>

      <div className="flex flex-wrap gap-3">
        <Link href={`/book/${booking.provider_id}`} className="rounded-pill">
          <Button>{t("summary.bookAgain")}</Button>
        </Link>
        <Link href="/browse" className="rounded-pill">
          <Button variant="ghost">{t("summary.backToListeners")}</Button>
        </Link>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { useRouter } from "next/navigation";
import { Star, CircleAlert } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Field, Input } from "@/components/ui/Field";
import { Chip } from "@/components/ui/Chip";
import { submitReview } from "@/app/(customer)/session/actions";
import { formatCents } from "@/lib/format";
import { t } from "@/lib/i18n";

const TIP_PRESETS = [0, 200, 500, 1000];

/**
 * Rate & tip after-screen, v2: flat on cream (DESIGN_SPEC_V2 §6) — star
 * radio buttons ≥48px with text labels, tip presets as toggle chips, one
 * labelled textarea.
 */
export function RatingTipForm({
  sessionId,
  providerId,
}: {
  sessionId: string;
  providerId: string;
}) {
  const router = useRouter();
  const [rating, setRating] = React.useState(0);
  const [tipCents, setTipCents] = React.useState(0);
  const [customTip, setCustomTip] = React.useState("");
  const [comment, setComment] = React.useState("");
  const [submitting, setSubmitting] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  function pickTip(cents: number) {
    setTipCents(cents);
    setCustomTip("");
  }

  async function onSubmit() {
    if (rating < 1) {
      setError(t("summary.chooseRating"));
      return;
    }
    setSubmitting(true);
    setError(null);
    const finalTip = customTip
      ? Math.max(0, Math.round(Number(customTip) * 100) || 0)
      : tipCents;
    const res = await submitReview({
      sessionId,
      providerId,
      rating,
      comment: comment.trim() || undefined,
      tipCents: finalTip,
    });
    if (res.error) {
      setError(res.error);
      setSubmitting(false);
      return;
    }
    router.refresh();
  }

  return (
    <div className="flex flex-col gap-8">
      {error ? (
        <p
          role="alert"
          className="flex items-start gap-2.5 rounded-card bg-alert-tint px-4 py-3.5 text-base text-ink"
        >
          <CircleAlert size={20} aria-hidden="true" className="mt-0.5 flex-none text-alert" />
          {error}
        </p>
      ) : null}

      <fieldset className="flex flex-col gap-3">
        <legend className="mb-3 text-h3">{t("summary.rateHeading")}</legend>
        <div role="radiogroup" className="flex gap-1">
          {[1, 2, 3, 4, 5].map((n) => (
            <button
              key={n}
              type="button"
              role="radio"
              aria-checked={rating === n}
              aria-label={t("summary.starLabel", { n })}
              onClick={() => setRating(n)}
              className="grid size-14 place-items-center rounded-sm transition-transform duration-200 active:scale-[0.94]"
            >
              <Star
                size={40}
                strokeWidth={2}
                aria-hidden="true"
                className={n <= rating ? "fill-accent text-accent" : "text-border-strong"}
              />
            </button>
          ))}
        </div>
      </fieldset>

      <fieldset className="flex flex-col gap-3">
        <legend className="mb-3 text-h3">{t("summary.tipHeading")}</legend>
        <p className="text-base text-ink-soft">{t("summary.tipHint")}</p>
        <div className="flex flex-wrap gap-2.5">
          {TIP_PRESETS.map((cents) => (
            <Chip
              key={cents}
              selected={!customTip && tipCents === cents}
              onClick={() => pickTip(cents)}
            >
              {cents === 0 ? t("summary.noTip") : formatCents(cents)}
            </Chip>
          ))}
        </div>
        <Field label={t("summary.tipCustomLabel")}>
          {(p) => (
            <Input
              {...p}
              type="number"
              inputMode="decimal"
              min={0}
              step="0.5"
              value={customTip}
              onChange={(e) => {
                setCustomTip(e.target.value);
                setTipCents(0);
              }}
              className="max-w-40"
            />
          )}
        </Field>
      </fieldset>

      <Field label={t("summary.thanksLabel")}>
        {(p) => (
          <textarea
            {...p}
            value={comment}
            onChange={(e) => setComment(e.target.value)}
            rows={3}
            maxLength={1000}
            placeholder={t("summary.thanksPlaceholder")}
            className="rounded-btn border-[1.5px] border-border-strong bg-surface px-4 py-3 text-base text-ink placeholder:text-ink-faint"
          />
        )}
      </Field>

      <Button full onClick={onSubmit} disabled={submitting}>
        {submitting ? t("ui.loading") : t("summary.submit")}
      </Button>
    </div>
  );
}

